package com.githubassistant.api;

import com.githubassistant.dto.*;import com.githubassistant.model.*;import com.githubassistant.repository.*;import com.githubassistant.service.*;
import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;import java.util.regex.*;

@RestController
@RequestMapping
@CrossOrigin(origins="${FRONTEND_ORIGIN:http://localhost:5173}")
public class ApiController {
    private final RepositoryRecordRepository repos;private final ChatMessageRepository messages;private final RepositoryIngestionService ingestion;private final SearchService search;private final GeminiService gemini;private final RepositoryExplorerService explorer;private final SearchHistoryService searchHistory;private final SavedLocationService savedLocations;
    private static final Pattern URL=Pattern.compile("^https://github\\.com/([A-Za-z0-9_.-]+)/([A-Za-z0-9_.-]+?)(?:\\.git)?/?$");
    public ApiController(RepositoryRecordRepository repos,ChatMessageRepository messages,RepositoryIngestionService ingestion,SearchService search,GeminiService gemini,RepositoryExplorerService explorer,SearchHistoryService searchHistory,SavedLocationService savedLocations){this.repos=repos;this.messages=messages;this.ingestion=ingestion;this.search=search;this.gemini=gemini;this.explorer=explorer;this.searchHistory=searchHistory;this.savedLocations=savedLocations;}
    @GetMapping("/") public Map<String,String> root(){return Map.of("service","GitHub Repository AI Assistant","status","ok");}
    @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok");}
    @PostMapping("/repositories") public ResponseEntity<?> create(@Valid @RequestBody CreateRepositoryRequest request){Matcher m=URL.matcher(request.url().trim());if(!m.matches())return ResponseEntity.badRequest().body(Map.of("error","Provide a public GitHub URL in the form https://github.com/owner/repository"));String owner=m.group(1).toLowerCase(Locale.ROOT),name=m.group(2).toLowerCase(Locale.ROOT),canonicalUrl="https://github.com/"+owner+"/"+name;RepositoryRecord r=repos.findFirstByUrlOrderByCreatedAtDesc(canonicalUrl).orElse(null);if(r!=null){if("failed".equals(r.getStatus())){r.setStatus("processing");r.setError(null);r.touch();r=repos.save(r);ingestion.index(r.getId());}return ResponseEntity.accepted().body(r);}r=new RepositoryRecord();r.setUrl(canonicalUrl);r.setOwner(owner);r.setName(name);r=repos.save(r);ingestion.index(r.getId());return ResponseEntity.accepted().body(r);}
    @GetMapping("/repositories/{id}") public ResponseEntity<?> get(@PathVariable String id){return repos.findById(id).<ResponseEntity<?>>map(ResponseEntity::ok).orElseGet(()->ResponseEntity.notFound().build());}
    @GetMapping("/repositories/{id}/search") public ResponseEntity<?> search(@PathVariable String id,@RequestParam String query){if(query.isBlank()||query.length()>1000)return ResponseEntity.badRequest().body(Map.of("error","Search query must be between 1 and 1000 characters."));if(repos.findById(id).isEmpty())return ResponseEntity.notFound().build();var found=search.search(id,query,8);searchHistory.record(id,query,"search",found.size());return ResponseEntity.ok(found);}
    @GetMapping("/repositories/{id}/explore") public ResponseEntity<?> explore(@PathVariable String id,@RequestParam(required=false) String query){if(query!=null&&query.length()>1000)return ResponseEntity.badRequest().body(Map.of("error","Search query must be at most 1000 characters."));RepositoryRecord repo=repos.findById(id).orElse(null);if(repo==null)return ResponseEntity.notFound().build();if(!"completed".equals(repo.getStatus()))return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","Repository indexing is "+repo.getStatus()));return ResponseEntity.ok(explorer.explore(repo,query));}
    @PostMapping("/repositories/{id}/explore") public ResponseEntity<?> explorePost(@PathVariable String id,@Valid @RequestBody ExploreRequest request){RepositoryRecord repo=repos.findById(id).orElse(null);if(repo==null)return ResponseEntity.notFound().build();if(!"completed".equals(repo.getStatus()))return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","Repository indexing is "+repo.getStatus()));String mode="trace".equalsIgnoreCase(request.mode())?"trace":"search";var result=explorer.explore(repo,request.query());searchHistory.record(id,request.query(),mode,result.results().size());return ResponseEntity.ok(result);}
    @GetMapping("/repositories/{id}/search-history") public ResponseEntity<?> searchHistory(@PathVariable String id){if(repos.findById(id).isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(searchHistory.recent(id));}
    @GetMapping("/repositories/{id}/saved-locations") public ResponseEntity<?> savedLocations(@PathVariable String id){if(repos.findById(id).isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(savedLocations.list(id));}
    @PostMapping("/repositories/{id}/saved-locations") public ResponseEntity<?> saveLocation(@PathVariable String id,@Valid @RequestBody SaveLocationRequest request){if(repos.findById(id).isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(savedLocations.save(id,request));}
    @DeleteMapping("/repositories/{id}/saved-locations/{locationId}") public ResponseEntity<?> removeSavedLocation(@PathVariable String id,@PathVariable String locationId){if(!savedLocations.remove(id,locationId))return ResponseEntity.notFound().build();return ResponseEntity.noContent().build();}
    @GetMapping("/repositories/{id}/ask") public ResponseEntity<?> askGet(@PathVariable String id,@RequestParam String query){return ask(id,query);}
    @PostMapping("/repositories/{id}/ask") public ResponseEntity<?> askPost(@PathVariable String id,@Valid @RequestBody AskRequest request){return ask(id,request.query());}
    private ResponseEntity<?> ask(String id,String query){if(query==null||query.isBlank()||query.length()>2000)return ResponseEntity.badRequest().body(Map.of("error","Question must be between 1 and 2000 characters."));RepositoryRecord repo=repos.findById(id).orElse(null);if(repo==null)return ResponseEntity.notFound().build();if(!"completed".equals(repo.getStatus()))return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error","Repository indexing is "+repo.getStatus()));List<ChatMessage> history=messages.findTop8ByRepositoryIdOrderByCreatedAtDesc(id).reversed();String historyText=history.stream().map(m->m.getRole()+": "+m.getContent()).reduce((a,b)->a+"\n"+b).orElse("");String retrievalQuery=query;if(!history.isEmpty()&&query.split("\\s+").length<7)retrievalQuery=history.stream().filter(m->m.getRole().equals("user")).reduce((a,b)->b).map(m->m.getContent()+" "+query).orElse(query);List<CodeChunk> found=search.search(id,retrievalQuery,6);String context=found.stream().map(c->"File: "+c.getFile()+" lines "+c.getStartLine()+"-"+c.getEndLine()+"\n"+c.getContent()).reduce((a,b)->a+"\n\n"+b).orElse("No relevant repository code was found.");String answer;try{answer=gemini.answer(query,historyText,context);}catch(Exception ex){return ResponseEntity.status(HttpStatus.BAD_GATEWAY).body(Map.of("error",ex.getMessage()));}messages.save(new ChatMessage(id,"user",query));messages.save(new ChatMessage(id,"assistant",answer));String branch=repo.getDefaultBranch()==null?"main":repo.getDefaultBranch();List<SourceReference> sources=found.stream().map(c->new SourceReference(c.getFile(),c.getStartLine(),c.getEndLine(),"https://github.com/"+repo.getOwner()+"/"+repo.getName()+"/blob/"+branch+"/"+c.getFile()+"#L"+c.getStartLine()+"-L"+c.getEndLine(),c.getContent())).toList();return ResponseEntity.ok(new AskResponse(answer,sources));}
    @GetMapping("/repositories/{id}/messages") public ResponseEntity<?> history(@PathVariable String id){if(repos.findById(id).isEmpty())return ResponseEntity.notFound().build();return ResponseEntity.ok(messages.findTop20ByRepositoryIdOrderByCreatedAtDesc(id).reversed());}
}
